// Instanced evaluation of the simple cubic (SC) strut lattice (D2).
//
// The unit cell is one copy of the lattice pattern (its 12 cube edges, from latticePattern("sc")).
// A field point is evaluated against the instances of that cell in its 3x3x3 neighbourhood, which is
// the same set strutLattice uses. Only one segment table exists: it is shared with the WGSL compute
// shader generated by scShaderSource(), so the GPU kernel and the CPU reference cannot drift apart.
//
// Instances are the cells of an nx x ny x nz lattice of cell size a. Cells outside the lattice are
// skipped, as in strutLattice, so the field is the union of the struts of the existing cells.

import { latticePattern } from "./lattice.ts";

type Vec3 = [number, number, number];

export interface ScInstanced {
  /** Cell size a (mm). */
  a: number;
  /** Strut radius r (mm), uniform. */
  r: number;
  /** Number of cells along x, y, z. */
  cells: Vec3;
}

/** Unit-cell segments, each as [start, end] in the unit cube [0,1]^3. */
export function unitCellSegments(): [Vec3, Vec3][] {
  return latticePattern("sc").map((s) => [
    [s[0], s[1], s[2]],
    [s[3], s[4], s[5]],
  ]);
}

function segDist(p: Vec3, a: Vec3, b: Vec3): number {
  const ab = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
  const ap = [p[0] - a[0], p[1] - a[1], p[2] - a[2]];
  const L2 = ab[0] * ab[0] + ab[1] * ab[1] + ab[2] * ab[2];
  const t = L2 > 0 ? Math.max(0, Math.min(1, (ap[0] * ab[0] + ap[1] * ab[1] + ap[2] * ab[2]) / L2)) : 0;
  return Math.hypot(ap[0] - t * ab[0], ap[1] - t * ab[1], ap[2] - t * ab[2]);
}

let cachedSegs: [Vec3, Vec3][] | null = null;

/** Instanced SC field value at p: min over the instances in the 3x3x3 neighbourhood of (distance - r). */
export function scInstancedValue(p: Vec3, lat: ScInstanced): number {
  const segs = (cachedSegs ??= unitCellSegments());
  const { a, r, cells } = lat;
  const ci = Math.floor(p[0] / a), cj = Math.floor(p[1] / a), ck = Math.floor(p[2] / a);
  let best = Infinity;
  for (let dk = -1; dk <= 1; dk++) {
    const k = ck + dk;
    if (k < 0 || k >= cells[2]) continue;
    for (let dj = -1; dj <= 1; dj++) {
      const j = cj + dj;
      if (j < 0 || j >= cells[1]) continue;
      for (let di = -1; di <= 1; di++) {
        const i = ci + di;
        if (i < 0 || i >= cells[0]) continue;
        const o: Vec3 = [i * a, j * a, k * a];
        for (const [s0, s1] of segs) {
          const d = segDist(p, [o[0] + s0[0] * a, o[1] + s0[1] * a, o[2] + s0[2] * a], [o[0] + s1[0] * a, o[1] + s1[1] * a, o[2] + s1[2] * a]) - r;
          if (d < best) best = d;
        }
      }
    }
  }
  return best;
}

/** WGSL compute shader for the same field. One invocation per grid point; the segment table is generated. */
export function scShaderSource(): string {
  const segs = unitCellSegments();
  const col = (v: Vec3) => `vec3<f32>(${v.map((x) => x.toFixed(1)).join(", ")})`;
  const e0 = segs.map((s) => col(s[0])).join(",\n    ");
  const e1 = segs.map((s) => col(s[1])).join(",\n    ");
  return `// Generated by src/topology/instanced.ts (scShaderSource). Do not edit by hand.
// SC strut lattice field on a regular grid: out[i] = min over instances (distance to strut - radius).
struct Params {
  origin: vec3<f32>,
  spacing: f32,
  dims: vec3<u32>,
  cell: f32,
  cells: vec3<u32>,
  radius: f32,
};

@group(0) @binding(0) var<uniform> P: Params;
@group(0) @binding(1) var<storage, read_write> outField: array<f32>;

const SEG0 = array<vec3<f32>, ${segs.length}>(
    ${e0}
);
const SEG1 = array<vec3<f32>, ${segs.length}>(
    ${e1}
);

fn segDist(p: vec3<f32>, a: vec3<f32>, b: vec3<f32>) -> f32 {
  let ab = b - a;
  let ap = p - a;
  let L2 = dot(ab, ab);
  var t = 0.0;
  if (L2 > 0.0) {
    t = clamp(dot(ap, ab) / L2, 0.0, 1.0);
  }
  return length(ap - t * ab);
}

@compute @workgroup_size(4, 4, 4)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
  if (id.x >= P.dims.x || id.y >= P.dims.y || id.z >= P.dims.z) {
    return;
  }
  let p = P.origin + P.spacing * vec3<f32>(id);
  let ci = i32(floor(p.x / P.cell));
  let cj = i32(floor(p.y / P.cell));
  let ck = i32(floor(p.z / P.cell));
  let nx = i32(P.cells.x);
  let ny = i32(P.cells.y);
  let nz = i32(P.cells.z);
  var best = 1.0e30;
  for (var dk = -1; dk <= 1; dk = dk + 1) {
    for (var dj = -1; dj <= 1; dj = dj + 1) {
      for (var di = -1; di <= 1; di = di + 1) {
        let i = ci + di;
        let j = cj + dj;
        let k = ck + dk;
        if (i >= 0 && i < nx && j >= 0 && j < ny && k >= 0 && k < nz) {
          let o = vec3<f32>(f32(i), f32(j), f32(k)) * P.cell;
          for (var e = 0u; e < ${segs.length}u; e = e + 1u) {
            let d = segDist(p, o + SEG0[e] * P.cell, o + SEG1[e] * P.cell) - P.radius;
            best = min(best, d);
          }
        }
      }
    }
  }
  let index = id.x + P.dims.x * (id.y + P.dims.y * id.z);
  outField[index] = best;
}
`;
}
